components.onTick:
const X = state.pts.map((p) => [p[0], p[1]]), Y = state.pts.map((p) => p[2]);
let net = state.net, loss = 0;
for (let i = 0; i < 5; i++) { const r = mlpStep(net, X, Y, state.lr); net = r.net; loss = r.loss; }
if (state.epoch >= 3000) return null;
return { net, loss: [...state.loss, round(loss, 4)].slice(-300), epoch: state.epoch + 5 };

components.draw:
const k = 24, g = range(k).map((r) => range(k).map((c) => mlpForward(state.net, [-1 + (c + 0.5) * 2 / k, 1 - (r + 0.5) * 2 / k]).out[0]));
return [
  heatmap(g, { x: [-1, 1], y: [-1, 1], min: 0, max: 1, color: 'orange' }),
  points(state.pts.map((p) => [p[0], p[1]]), { colors: state.pts.map((p) => p[2] ? 'orange' : 'blue'), r: 4 }),
  point(state.probe[0], state.probe[1], { id: 'probe', draggable: true, color: 'gray', r: 8 })
];
